<!doctype html><html lang="en"><head>@include('bn_font')<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>You're Offline</title><meta name="robots" content="noindex"><meta name="theme-color" content="#0B1220">
<style>:root{--o:#FF5A00;--n:#0B1220}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#fff;color:var(--n);font-family:Inter,'Bornomala',sans-serif;text-align:center;padding:24px}
.c{max-width:360px}.c img{width:96px;height:auto;margin-bottom:18px}.ic{width:64px;height:64px;border-radius:20px;background:#FFF1E6;color:var(--o);display:flex;align-items:center;justify-content:center;margin:0 auto 14px}
h1{font-size:24px;margin:0 0 8px}p{color:#6B7280;margin:0 0 22px;line-height:1.5}button{border:0;background:linear-gradient(135deg,#FF7A1A,#FF5A00);color:#fff;font-weight:700;font-size:16px;border-radius:14px;padding:13px 28px;box-shadow:0 8px 18px rgba(255,90,0,.3);cursor:pointer}</style></head>
<body><div class="c"><img src="/pwa/logo-240.png" alt="DutyFreeBD" width="96" height="104"><div class="ic"><svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 8.8a15 15 0 0 1 20 0M5 12.5a10 10 0 0 1 14 0M8.5 16a5 5 0 0 1 7 0"/><circle cx="12" cy="19.5" r="1" fill="currentColor"/><path d="M3 3l18 18"/></svg></div>
<h1>You’re Offline</h1><p>Please check your internet connection and try again.<br>Orders and payments cannot be completed offline.</p><button type="button" onclick="location.reload()">Try again</button></div>
<script>addEventListener('online',function(){location.reload()})</script></body></html>
